    Bug 1675044 - Properly reject pending Promise of RTCPeerConnection.createOffer(). r=aleca


    Thunderbird does not support WebRTC, but it should properly reject calls
    to `RTCPeerConnection.createOffer()` and inform the user about the
    missing support.

    Differential Revision: https://phabricator.services.mozilla.com/D236249

diff --git a/mail/actors/BrowserProcessChild.sys.mjs b/mail/actors/BrowserProcessChild.sys.mjs
new file mode 100644
index 00000000000..f84c07a28e3
--- /dev/null
+++ b/mail/actors/BrowserProcessChild.sys.mjs
@@ -0,0 +1,19 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+export class BrowserProcessChild extends JSProcessActorChild {
+  observe(subject, topic, _data) {
+    switch (topic) {
+      case "PeerConnection:request": {
+        console.warn("WebRTC support not implemented");
+        Services.obs.notifyObservers(
+          null,
+          "PeerConnection:response:deny",
+          subject.callID
+        );
+        break;
+      }
+    }
+  }
+}
